/* Regional overview. Public listings, regional posts and published notices share a scope. */
const NH_TABS=[['overview','grid','Тойм'],['listings','apartment','Зарууд'],['map','map','Ойр орчим'],['news','bell','Мэдээ'],['stories','message','Хөршүүд']];
const NH_CATEGORIES=[['question','Асуулт'],['tip','Зөвлөгөө'],['life','Өдөр тутам']];
const NH_PLACES={schools:{label:'Сургууль',icon:'school',query:'["amenity"~"^(school|kindergarten)$"]'},health:{label:'Эмнэлэг',icon:'heart',query:'["amenity"~"^(hospital|clinic|pharmacy)$"]'},shops:{label:'Дэлгүүр',icon:'briefcase',query:'["shop"~"^(supermarket|convenience)$"]'},food:{label:'Кафе',icon:'coffee',query:'["amenity"~"^(cafe|restaurant)$"]'},parks:{label:'Цэцэрлэгт хүрээлэн',icon:'tree',query:'["leisure"="park"]'},transit:{label:'Автобус',icon:'bus',query:'["highway"="bus_stop"]'}};
const NH_SOURCES=[{icon:'wind',title:'Агаарын чанар',body:'Хэмжилтийн станцын мэдээлэл, хэмжсэн хугацааг албан эх сурвалжаас шалгана.',url:'https://tsag-agaar.gov.mn/environmental',source:'ЦУОШГ',ub:false},{icon:'bus',title:'Нийтийн тээвэр',body:'Чиглэл, зогсоолын мэдээллийг албан үйлчилгээ дээрээс үзнэ.',url:'https://www.ubtransport.mn/',source:'Нийтийн тээврийн бодлогын газар',ub:true},{icon:'chart',title:'Бүсийн статистик',body:'Албан статистик нь зарын үнээс тусдаа мэдээлэл юм.',url:'https://www.1212.mn/',source:'Үндэсний статистикийн хороо',ub:false}];
let nhScope={province:'Улаанбаатар',area:'',khoroo:''},nhTab='overview',nhFilters={type:'all',deal:'all',rooms:'all',sort:'new',q:'',page:0},nhPriceType='0',nhPriceDeal='rent',nhPlaceCategory='schools',nhStoryCategory='all',nhPlaceLimit=12;
let nhMap=null,nhMapObserver=null,nhPlaceRequest=null,nhRequestVersion=0;
const nhPlaceCache=new Map();
function nhCleanScope(raw={}){
 const province=MONGOLIA_PROVINCES.includes(raw.province)?raw.province:'Улаанбаатар';
 const area=province==='Улаанбаатар'&&Object.hasOwn(UB_KHOROO_COUNTS,raw.area)?raw.area:'';
 const khoroo=area&&Array.from({length:UB_KHOROO_COUNTS[area]},(_,i)=>(i+1)+'-р хороо').includes(raw.khoroo)?raw.khoroo:'';
 return {province,area,khoroo};
}
function nhScopeKey(scope=nhScope){return [scope.province,scope.area,scope.khoroo].filter(Boolean).join('/')}
function nhScopeLabel(scope=nhScope){return [scope.province,scope.area,scope.khoroo].filter(Boolean).join(' · ')}
function nhScopeFromKey(key){const [province,area='',khoroo='']=String(key||'').split('/');return nhCleanScope({province,area,khoroo})}
function nhState(){
 if(!flowState.neighborhood||typeof flowState.neighborhood!=='object'||Array.isArray(flowState.neighborhood))flowState.neighborhood={};
 const s=flowState.neighborhood;s.selection=nhCleanScope(s.selection||{});
 s.followed=Array.isArray(s.followed)?[...new Set(s.followed.filter(v=>typeof v==='string'&&nhScopeKey(nhScopeFromKey(v))===v))].slice(0,20):[];
 s.likes=Array.isArray(s.likes)?s.likes.filter(v=>typeof v==='string').slice(0,1000):[];return s;
}
function nhReadRoute(){
 const parts=(location.hash||'#/community').slice(2).split('/');let next=nhState().selection,tab='overview';
 if(parts.length>1){try{next=nhCleanScope({province:decodeURIComponent(parts[1]),area:decodeURIComponent(parts[2]||''),khoroo:decodeURIComponent(parts[3]||'')});tab=NH_TABS.some(t=>t[0]===parts[4])?parts[4]:'overview'}catch{next=nhState().selection}}
 if(nhScopeKey(next)!==nhScopeKey()){nhFilters={type:'all',deal:'all',rooms:'all',sort:'new',q:'',page:0};nhStoryCategory='all';nhPlaceLimit=12;nhCancelPlaces()}
 nhScope=next;nhTab=tab;
}
function nhUrl(scope=nhScope,tab=nhTab){return '#/community/'+[scope.province,scope.area,scope.khoroo].map(encodeURIComponent).join('/')+'/'+tab}
function nhNavigate(scope,tab=nhTab){
 const next=nhCleanScope(scope),s=nhState(),before=JSON.stringify(s);s.selection=next;
 if(!persistFlows()){flowState.neighborhood=JSON.parse(before);render();return}
 closeOverlay();if(location.hash===nhUrl(next,tab))render();else location.hash=nhUrl(next,tab);
}
function nhChooseRegion(field,value){const next={...nhScope,[field]:value};if(field==='province'){next.area='';next.khoroo=''}if(field==='area')next.khoroo='';nhNavigate(next)}
function nhSelectTab(tab){if(NH_TABS.some(t=>t[0]===tab))nhNavigate(nhScope,tab)}
function nhFollow(){const s=nhState(),before=JSON.stringify(s),key=nhScopeKey();if(s.followed.includes(key))s.followed=s.followed.filter(v=>v!==key);else if(s.followed.length<20)s.followed.push(key);else return toast('20 хүртэл байршил хадгална.');if(!persistFlows()){flowState.neighborhood=JSON.parse(before);return}render()}
function nhMatches(record,scope=nhScope,includeParent=false){
 if(record.province!==scope.province)return false;
 if(scope.area&&record.area!==scope.area&&!(includeParent&&!record.area))return false;
 return !scope.khoroo||record.khoroo===scope.khoroo||(includeParent&&!record.khoroo);
}
function nhHomes(){return homes.filter(h=>isPublicListing(h)&&nhMatches(h))}
function nhPosts(category=nhStoryCategory){return flowState.posts.filter(p=>p.adminStatus!=='hidden'&&nhMatches(p,nhScope,true)&&(category==='all'||p.category===category)).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))}
function nhNotices(){return adminNotices().filter(n=>n.status==='published'&&(!n.province||nhMatches(n,nhScope,true))).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))}
function nhLegacyPosts(){return flowState.posts.filter(p=>!p.province&&p.adminStatus!=='hidden')}
function nhOffices(){const ids=[...new Set(nhHomes().map(h=>officeIdentity(h)?.officeId).filter(Boolean))];return ids.map(id=>officePublicModel(id)).filter(Boolean).map(m=>({...m,regionCount:officePublicHomes(m.id).filter(h=>nhMatches(h)).length})).filter(m=>m.regionCount)}
function nhMedian(values){const a=values.filter(v=>Number.isFinite(v)&&v>0).slice().sort((a,b)=>a-b);return a.length?a.length%2?a[(a.length-1)/2]:(a[a.length/2-1]+a[a.length/2])/2:null}
function nhPriceGroups(){
 const list=nhHomes().filter(h=>h.type===Number(nhPriceType)&&h.deal===nhPriceDeal&&Number.isFinite(h.price)&&h.price>0&&(h.deal==='sale'||(h.rentPeriod||'month')==='month'));
 return ['1','2','3','4','5+','shared'].map(room=>{const rows=list.filter(h=>room==='shared'?h.rooms==='shared':room==='5+'?Number(h.rooms)>=5:String(h.rooms)===room);return {room,label:room==='shared'?'Хажуу өрөө':room+' өрөө',count:rows.length,median:nhMedian(rows.map(h=>h.price)),demoCount:rows.filter(h=>!h.local).length}});
}
function nhSelectPrice(field,value){if(field==='type'&&['0','1'].includes(value))nhPriceType=value;if(field==='deal'&&['rent','sale'].includes(value))nhPriceDeal=value;render()}
function nhRegionControls(){const s=nhState(),followed=s.followed.includes(nhScopeKey());return `<div class="nh-region-controls"><label>Хот / Аймаг<select aria-label="Хорооллын хот, аймаг" onchange="nhChooseRegion('province',this.value)">${MONGOLIA_PROVINCES.map(p=>`<option ${p===nhScope.province?'selected':''}>${p}</option>`).join('')}</select></label><label>Дүүрэг<select aria-label="Хорооллын дүүрэг" ${nhScope.province!=='Улаанбаатар'?'disabled':''} onchange="nhChooseRegion('area',this.value)"><option value="">Бүх дүүрэг</option>${Object.keys(UB_KHOROO_COUNTS).map(p=>`<option ${p===nhScope.area?'selected':''}>${p}</option>`).join('')}</select></label><label>Хороо<select aria-label="Хорооллын хороо" ${!nhScope.area?'disabled':''} onchange="nhChooseRegion('khoroo',this.value)"><option value="">Бүх хороо</option>${Array.from({length:UB_KHOROO_COUNTS[nhScope.area]||0},(_,i)=>(i+1)+'-р хороо').map(p=>`<option ${p===nhScope.khoroo?'selected':''}>${p}</option>`).join('')}</select></label><button class="nh-follow ${followed?'is-followed':''}" type="button" aria-pressed="${followed}" onclick="nhFollow()">${icon(followed?'check':'bookmark')}<span>${followed?'Хадгалсан':'Байршил хадгалах'}</span></button></div>${s.followed.length?'<div class="nh-followed" aria-label="Хадгалсан байршлууд">'+s.followed.map(key=>`<a href="${nhUrl(nhScopeFromKey(key),'overview')}">${icon('pin')}${esc(nhScopeLabel(nhScopeFromKey(key)))}</a>`).join('')+'</div>':''}${nhScope.province!=='Улаанбаатар'?'<p class="nh-region-note">Аймгийг бүхэлд нь харуулж байна. Сум, багийн нарийвчилсан сонголт хараахан холбогдоогүй.</p>':''}`}
function neighborhoodPage(){
 nhReadRoute();const list=nhHomes(),stats=[['apartment','Нийтэд харагдах зар',list.length],['key','Түрээсийн зар',list.filter(h=>h.deal==='rent').length],['house','Худалдах зар',list.filter(h=>h.deal==='sale').length],['message','Хөршүүдийн нийтлэл',nhPosts('all').length]];
 return `<div class="wrap nh-page"><section class="nh-hero"><div class="nh-hero-copy"><div><span class="nh-eyebrow">ӨРӨӨ · МАНАЙ ХОРООЛОЛ</span><h1>Таны хороолол, нэг дор.</h1><p>${icon('pin')}${esc(nhScopeLabel())}</p></div><div class="nh-hero-mark" aria-hidden="true">${icon('house')}<span>${icon('users')}</span></div></div>${nhRegionControls()}</section><div class="nh-demo-notice">${icon('info')}<span>Локал демо · Зарын жишээ өгөгдөл нь бодит зах зээлийн статистик биш. Гадаад мэдээллийн эх сурвалжийг тусад нь тэмдэглэнэ.</span></div><div class="nh-metrics">${stats.map(([glyph,label,value])=>`<div><span>${icon(glyph)}${label}</span><b>${value}<small>${glyph==='message'?'нийтлэл':'зар'}</small></b></div>`).join('')}</div><nav class="nh-tabs" aria-label="Хорооллын мэдээлэл">${NH_TABS.map(([key,glyph,label])=>`<a href="${nhUrl(nhScope,key)}" ${key===nhTab?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span>${key==='listings'?'<b>'+list.length+'</b>':''}</a>`).join('')}</nav><div class="nh-layout"><div class="nh-main">${nhTab==='overview'?nhOverview():nhTab==='listings'?nhListingSection():nhTab==='map'?nhNearbySection():nhTab==='news'?nhNewsSection():nhStoriesSection()}</div><aside class="nh-sidebar">${nhTab==='overview'?nhPricePanel():nhScopePanel()}${nhOfficePanel()}${nhSourcesPanel()}</aside></div><p class="nh-footnote">Мэдээллийн хүрээ: ${esc(nhScopeLabel())} · Зөвхөн нийтэд харагдах зар, нийтлэл болон нийтэлсэн мэдээ. Хувийн холбоо барих мэдээлэл, дотоод хяналтын материал орохгүй.</p></div>`;
}
function nhHeading(eyebrow,title,action=''){return `<div class="nh-section-heading"><div><span>${eyebrow}</span><h2>${title}</h2></div>${action}</div>`}
function nhOverview(){const list=nhSortedHomes();return `<section class="nh-panel">${nhHeading('ТАНЫ СОНГОСОН БҮС','Энэ хорооллын орон зай',`<a href="${nhUrl(nhScope,'listings')}">Бүх зар ${icon('arrow-right')}</a>`)}${list.length?`<div class="cards nh-property-grid">${list.slice(0,3).map(card).join('')}</div>`:nhEmpty('Энэ бүсэд нийтэд харагдах зар алга','Өөр дүүрэг сонгох эсвэл өөрийн зараа нэмээрэй.','<a class="nh-text-link" href="#/listing/new">Зар нэмэх '+icon('plus')+'</a>')}</section><section class="nh-panel">${nhHeading('ӨДӨР ТУТМЫН АМЬДРАЛ','Ойр орчноо таньж мэдээрэй',`<a href="${nhUrl(nhScope,'map')}">Газрын зураг ${icon('arrow-right')}</a>`)}${nhMapMarkup(false)}<div class="nh-place-shortcuts">${Object.entries(NH_PLACES).map(([key,p])=>`<button type="button" onclick="nhPlaceCategory='${key}';nhSelectTab('map')">${icon(p.icon)}<span>${p.label}</span>${icon('chevron-right')}</button>`).join('')}</div><p class="nh-source-note">Төв цэгийн ойролцоох OpenStreetMap мэдээллийг хүсэлтээр ачаална. Хороо, дүүргийн албан хил болон алхах хугацааны тооцоо биш.</p></section><section class="nh-panel">${nhHeading('МЭДЭЭ БА ЗАРЛАЛ','Сүүлийн мэдээлэл',`<a href="${nhUrl(nhScope,'news')}">Бүгд ${icon('arrow-right')}</a>`)}${nhNoticeCards(3)}</section><section class="nh-panel">${nhHeading('ХӨРШҮҮДТЭЙГЭЭ ХОЛБОГДООРОЙ','Хорооллын яриа',`<button class="nh-small-button" onclick="communityPost()">${icon('plus')}Нийтлэл бичих</button>`)}${nhPostCards(nhPosts('all').slice(0,3))}<a class="nh-text-link" href="${nhUrl(nhScope,'stories')}">Бүх яриа ${icon('arrow-right')}</a></section>`}
function nhEmpty(title,body,action=''){return `<div class="nh-empty">${icon('map')}<b>${title}</b><p>${body}</p>${action}</div>`}
function nhPricePanel(){const rows=nhPriceGroups(),n=rows.reduce((a,r)=>a+r.count,0);return `<section class="nh-panel nh-price-panel">${nhHeading('ЗАРЫН ҮНЭ · ₮','Үнийн баримжаа')}<div class="nh-price-selects"><label>Төрөл<select aria-label="Үнийн мэдээллийн төрөл" onchange="nhSelectPrice('type',this.value)"><option value="0" ${nhPriceType==='0'?'selected':''}>Орон сууц</option><option value="1" ${nhPriceType==='1'?'selected':''}>Хаус</option></select></label><label>Гэрээ<select aria-label="Үнийн мэдээллийн гэрээ" onchange="nhSelectPrice('deal',this.value)"><option value="rent" ${nhPriceDeal==='rent'?'selected':''}>Сарын түрээс</option><option value="sale" ${nhPriceDeal==='sale'?'selected':''}>Худалдах</option></select></label></div><p class="nh-price-caption">Байршуулсан үнийн медиан${nhPriceDeal==='rent'?' · ₮ / сар':''}</p><div class="nh-price-rows">${rows.map(r=>`<div><span>${r.label}<small>${r.count} зар</small></span><b>${r.median!==null?formatMnt(Math.round(r.median)):'—'}</b></div>`).join('')}</div><p class="nh-source-note">${n} нийтэд харагдах зар · ${esc(nhScopeLabel())}. Ижил төрөл, өрөөний тоогоор бүлэглэв. ${nhPriceDeal==='rent'?'Зөвхөн сарын түрээс; өдрийн, долоо хоногийн үнийг оруулаагүй.':''} Бодит хэлцлийн үнэ биш. Цөөн зар нь нийт зах зээлийг төлөөлөхгүй.</p><span class="nh-data-label">${nhHomes().some(h=>!h.local)?'Жишээ зар агуулсан тооцоо':'Энэ браузерт байршуулсан зар'}</span></section>`}
function nhScopePanel(){return `<section class="nh-panel nh-scope-panel"><span class="nh-eyebrow">ТАНЫ СОНГОСОН БҮС</span><h3>${esc(nhScope.area||nhScope.province)}</h3><p>${esc(nhScope.khoroo||'Бүх байршил')}</p><button class="nh-outline-button" onclick="nhViewPropertyMap()">${icon('map')}Зарын газрын зураг</button><a class="nh-text-link" href="${nhUrl(nhScope,'overview')}">Тойм руу ${icon('arrow-right')}</a></section>${nhPricePanel()}`}
function nhOfficePanel(){const list=nhOffices();return `<section class="nh-panel nh-office-panel">${nhHeading('ЗУУЧЛАЛЫН БАЙГУУЛЛАГУУД','Танд туслах хүмүүс')}<p class="nh-source-note">Энэ бүсэд нийтэд харагдах зар байршуулсан байгууллагууд.</p>${list.map(m=>`<a class="nh-office-row" href="#/offices/${m.id}" onclick="officeReturnListing=null;officeResetFilters('${m.id}')"><span class="nh-office-avatar">${officeAvatar(m)}</span><span><b>${esc(m.name)}</b>${officeBadge(m)}<small>${m.regionCount} зар · Сонгосон бүс</small></span>${icon('chevron-right')}</a>`).join('')||'<p class="nh-muted">Одоогоор энэ бүсэд нийтэд нээлттэй байгууллага алга.</p>'}<a class="nh-text-link" href="#/offices">Байгууллагуудыг харах ${icon('arrow-right')}</a></section>`}
function nhSourcesPanel(){return `<section class="nh-panel nh-sources-panel"><h3>${icon('shield')}Эх сурвалж ба шинэчлэлт</h3><p>Зар, нийтлэл: энэ браузерт хадгалсан мэдээлэл. Газрын зураг: OpenFreeMap / OpenStreetMap.</p><p>Агаарын чанар, тээврийн шууд мэдээлэл хараахан холбогдоогүй.</p><a class="nh-text-link" href="${nhUrl(nhScope,'news')}">Албан эх сурвалжууд ${icon('arrow-right')}</a></section>`}
function nhSortedHomes(){let list=nhHomes().filter(h=>(nhFilters.type==='all'||h.type===Number(nhFilters.type))&&(nhFilters.deal==='all'||h.deal===nhFilters.deal)&&(nhFilters.rooms==='all'||(nhFilters.rooms==='5+'?Number(h.rooms)>=5:String(h.rooms)===nhFilters.rooms))&&(!nhFilters.q||[h.name,h.id,h.desc,h.address].join(' ').toLowerCase().includes(nhFilters.q.toLowerCase())));return list.slice().sort((a,b)=>nhFilters.sort==='price'?(Number.isFinite(a.price)?a.price:Infinity)-(Number.isFinite(b.price)?b.price:Infinity):nhFilters.sort==='price-desc'?(Number.isFinite(b.price)?b.price:-Infinity)-(Number.isFinite(a.price)?a.price:-Infinity):String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')))}
function nhListingFilter(field,value){if(!['type','deal','rooms','sort'].includes(field))return;const search=document.querySelector('.nh-listing-filters [name=q]');if(search)nhFilters.q=search.value.trim();nhFilters[field]=value;nhFilters.page=0;render()}
function nhSearchListings(event){event.preventDefault();nhFilters.q=String(new FormData(event.target).get('q')||'').trim();nhFilters.page=0;render()}
function nhResetListings(){nhFilters={type:'all',deal:'all',rooms:'all',sort:'new',q:'',page:0};render()}
function nhListingSection(){const list=nhSortedHomes(),pages=Math.ceil(list.length/9);nhFilters.page=Math.min(nhFilters.page,Math.max(0,pages-1));return `<section class="nh-panel">${nhHeading('ТАНЫ СОНГОСОН БҮС',`Нийтэд харагдах ${list.length} зар`,`<button class="nh-small-button" onclick="nhViewPropertyMap()">${icon('map')}Газрын зураг</button>`)}<form class="nh-listing-filters" onsubmit="nhSearchListings(event)"><label class="nh-list-search">${icon('search')}<input name="q" aria-label="Хорооллын зар хайх" placeholder="Нэр, хаяг, зарын дугаар" value="${esc(nhFilters.q)}"></label><select aria-label="Хорооллын зарын төрөл" onchange="nhListingFilter('type',this.value)"><option value="all">Бүх төрөл</option>${types.map((t,i)=>`<option value="${i}" ${nhFilters.type===String(i)?'selected':''}>${t}</option>`).join('')}</select><select aria-label="Хорооллын гэрээний төрөл" onchange="nhListingFilter('deal',this.value)">${[['all','Түрээс / Худалдах'],['rent','Түрээс'],['sale','Худалдах']].map(([k,t])=>`<option value="${k}" ${nhFilters.deal===k?'selected':''}>${t}</option>`).join('')}</select><select aria-label="Хорооллын өрөөний тоо" onchange="nhListingFilter('rooms',this.value)">${[['all','Бүх өрөө'],...['1','2','3','4','5+'].map(n=>[n,n+' өрөө']),['shared','Хажуу өрөө']].map(([k,t])=>`<option value="${k}" ${nhFilters.rooms===k?'selected':''}>${t}</option>`).join('')}</select><select aria-label="Хорооллын эрэмбэ" onchange="nhListingFilter('sort',this.value)">${[['new','Шинэ нь эхэнд'],['price','Үнэ өсөхөөр'],['price-desc','Үнэ буурахаар']].map(([k,t])=>`<option value="${k}" ${nhFilters.sort===k?'selected':''}>${t}</option>`).join('')}</select><button class="primary">Хайх</button><button type="button" onclick="nhResetListings()">Цэвэрлэх</button></form><div class="cards nh-property-grid">${list.slice(nhFilters.page*9,nhFilters.page*9+9).map(card).join('')}</div>${!list.length?nhEmpty('Тохирох зар олдсонгүй','Өөр байршил эсвэл шүүлтүүр сонгоно уу.'):''}${pages>1?`<div class="nh-pagination" aria-label="Зарын хуудас">${Array.from({length:pages},(_,i)=>`<button ${nhFilters.page===i?'aria-current="page"':''} onclick="nhFilters.page=${i};render()">${i+1}</button>`).join('')}</div>`:''}</section>`}
function nhViewPropertyMap(){query='';filter={...defaultFilter(),locations:[nhScopeKey()]};category=-1;activeDetail=null;goFlow('map')}
function nhFromPropertyMap(){const key=filter.locations?.length===1?filter.locations[0]:null;nhNavigate(key?nhScopeFromKey(key):areas.includes(query)?nhCleanScope({province:'Улаанбаатар',area:query}):nhState().selection,'overview')}
function nhMapCenter(){if(nhScope.province!=='Улаанбаатар')return null;if(!nhScope.area)return {lat:47.9189,lng:106.917,label:'Улаанбаатарын ерөнхий төв цэг'};const point=districtLocations[nhScope.area];return point?{lat:point[0],lng:point[1],label:nhScope.area+' · Дүүргийн ерөнхий төв цэг'}:null}
function nhMapMarkup(large=true){const center=nhMapCenter();return `<div class="nh-map-frame ${large?'is-large':''}"><div id="nh-map" aria-label="Хорооллын газрын зураг"></div><div class="nh-map-controls"><button aria-label="Ойр орчмын зураг ойртуулах" onclick="nhMap?.zoomIn()">${icon('plus')}</button><button aria-label="Ойр орчмын зураг холдуулах" onclick="nhMap?.zoomOut()">${icon('minus')}</button></div><p class="nh-map-status" role="status">Газрын зураг ачаалж байна…</p><div class="nh-map-legend"><span><i></i>Нийтэд харагдах зар</span><span><i></i>OSM байгууламж</span></div></div><p class="nh-map-caption">${icon('pin')}${esc(center?.label||'Монголын ерөнхий зураг · Бүсийн төв цэг холбогдоогүй')}${nhScope.khoroo?' · Хорооны нарийн хил, төв цэг холбогдоогүй.':''}</p>`}
function nhSelectPlaceCategory(key){if(Object.hasOwn(NH_PLACES,key)){nhPlaceCategory=key;nhPlaceLimit=12;render()}}
function nhPlaceEntry(){const center=nhMapCenter();return center?nhPlaceCache.get([center.lat,center.lng,nhPlaceCategory].join('|')):null}
function nhNearbySection(){const p=NH_PLACES[nhPlaceCategory],entry=nhPlaceEntry(),center=nhMapCenter();return `<section class="nh-panel">${nhHeading('ГАЗРЫН ЗУРАГ БА ҮЙЛЧИЛГЭЭ','Таны ойр орчим')}<p class="nh-muted">Байгууламжийг сонгосон ерөнхий төв цэгээс 1 км радиуст хайна. Энэ нь дүүрэг, хорооны бүх байгууламжийн тооллого биш.</p><div class="nh-place-categories">${Object.entries(NH_PLACES).map(([key,p])=>`<button ${nhPlaceCategory===key?'aria-pressed="true"':'aria-pressed="false"'} onclick="nhSelectPlaceCategory('${key}')">${icon(p.icon)}${p.label}</button>`).join('')}</div>${nhMapMarkup()}<div class="nh-places-head"><div><h3>${p.label}${entry?.items?.length?' · '+entry.items.length:''}</h3><p>${entry?.fetchedAt?'OSM · '+esc(entry.fetchedAt):'OpenStreetMap · Хүсэлтээр ачаална'}</p></div><button class="nh-outline-button" ${!center||entry?.status==='loading'?'disabled':''} onclick="nhLoadPlaces()">${icon('refresh')}${entry?.status==='loading'?'Ачаалж байна…':entry?.fetchedAt?'Шинэчлэх':'Ойр орчмыг ачаалах'}</button></div>${!center?nhEmpty('Хайлтын төв цэг хараахан холбогдоогүй','Энэ бүсийн нийтэд харагдах заруудыг Зарууд хэсгээс үзнэ үү.'):entry?.status==='error'?`<div class="nh-service-state" role="status">${icon('info')}<p>OSM мэдээлэл ачаалж чадсангүй. Түр хүлээгээд дахин оролдоно уу. Өмнө ачаалсан мэдээлэл байвал доор харуулна.</p></div>`:entry?.status==='loading'?'<p class="nh-service-state" role="status">OSM мэдээлэл ачаалж байна…</p>':!entry||entry.status==='idle'?'<div class="nh-service-state">'+icon('map')+'<p>Товчийг дарж сонгосон төвийн ойролцоох бодит OSM мэдээллийг ачаална.</p></div>':''}${entry?.items?.length?`<div class="nh-place-list">${entry.items.slice(0,nhPlaceLimit).map(item=>`<button class="nh-place-row" data-place="${item.key}" onclick="nhOpenPlace(this.dataset.place)"><i>${icon(p.icon)}</i><span><b>${esc(item.name)}</b><small>${Math.round(item.distance)} м · Шулуун зай</small></span>${icon('chevron-right')}</button>`).join('')}</div>${entry.items.length>nhPlaceLimit?'<button class="nh-outline-button nh-more-places" onclick="nhPlaceLimit+=12;render()">Илүү харах · '+Math.min(nhPlaceLimit,entry.items.length)+' / '+entry.items.length+'</button>':''}`:entry?.status==='success'?nhEmpty('Энэ хайлтаар бүртгэл олдсонгүй','Тухайн үйлчилгээ байхгүй гэсэн үг биш. OSM бүртгэл дутуу байж болно.'):''}<p class="nh-source-note">© OpenStreetMap contributors · Нэг хүсэлтээр 80 хүртэл бүртгэл. Нэр, байршил нь олон нийтээр бүрдүүлсэн мэдээлэл; ажиллах цаг, хаягийг тухайн байгууллагаас нягтлаарай. Алхах хугацаа тооцоогүй.</p></section><section class="nh-panel">${nhHeading('ОРОН СУУЦ СОНГОХДОО','Байр бүр дээр шалгах зүйлс')}<div class="nh-living-grid">${[['thermometer','Халаалт','Төвлөрсөн эсвэл бие даасан халаалт, өвлийн төлбөр.'],['garage','Зогсоол','Гаражийн боломж, төлбөр ба нэвтрэх нөхцөл.'],['wallet','СӨХ ба ашиглалт','СӨХ, ус, цахилгаан болон нэмэлт төлбөр.']].map(([glyph,title,body])=>`<div>${icon(glyph)}<h3>${title}</h3><p>${body}</p></div>`).join('')}</div><p class="nh-source-note">Ерөнхий шалгах жагсаалт. Энэ бүсийн бодит үнэлгээ, дэд бүтцийн баталгаа биш.</p></section>`}
function nhDistance(a,b){const rad=n=>n*Math.PI/180,dlat=rad(b.lat-a.lat),dlng=rad(b.lng-a.lng),v=Math.sin(dlat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dlng/2)**2;return 6371000*2*Math.atan2(Math.sqrt(v),Math.sqrt(Math.max(0,1-v)))}
function nhParsePlaces(data,center,category=nhPlaceCategory){const seen=new Set();return (Array.isArray(data?.elements)?data.elements:[]).slice(0,80).map(e=>{const lat=e.lat??e.center?.lat,lng=e.lon??e.center?.lon,key=e.type+'/'+e.id;if(!['node','way','relation'].includes(e.type)||!Number.isSafeInteger(e.id)||e.id<1||!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180||seen.has(key))return null;seen.add(key);const distance=nhDistance(center,{lat,lng});return distance<=1000?{key,lat,lng,distance,name:String(e.tags?.['name:mn']||e.tags?.name||NH_PLACES[category].label).slice(0,200)}:null}).filter(Boolean).sort((a,b)=>a.distance-b.distance)}
function nhCancelPlaces(){nhPlaceRequest?.abort();nhPlaceRequest=null;nhRequestVersion++;for(const [key,entry] of nhPlaceCache)if(entry.status==='loading')nhPlaceCache.set(key,{...entry,status:entry.fetchedAt?'success':'idle'})}
async function nhLoadPlaces(){
 const center=nhMapCenter(),category=nhPlaceCategory,requestedHash=location.hash;if(!center||!Object.hasOwn(NH_PLACES,category))return;const key=[center.lat,center.lng,category].join('|'),old=nhPlaceCache.get(key),now=Date.now();
 if(old?.status==='loading')return;if(old?.attempt&&now-old.attempt<15000)return toast('Түр хүлээгээд дахин оролдоно уу.');
 nhCancelPlaces();const controller=new AbortController(),version=++nhRequestVersion;nhPlaceRequest=controller;
 nhPlaceCache.set(key,{...old,status:'loading',attempt:now,items:old?.items||[]});render();
 const timer=setTimeout(()=>controller.abort(),22000),query='[out:json][timeout:15];nwr'+NH_PLACES[category].query+'(around:1000,'+center.lat+','+center.lng+');out center 80;';
 try{const response=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'data='+encodeURIComponent(query),credentials:'omit',signal:controller.signal});if(!response.ok)throw Error('OSM response');const data=await response.json();if(!Array.isArray(data?.elements)||data.remark)throw Error('Incomplete OSM response');if(version!==nhRequestVersion)return;nhPlaceCache.set(key,{status:'success',items:nhParsePlaces(data,center,category),fetchedAt:new Date().toLocaleString('sv-SE',{timeZone:'Asia/Ulaanbaatar',hour12:false}),attempt:now});}
 catch{if(version===nhRequestVersion)nhPlaceCache.set(key,{...old,status:'error',items:old?.items||[],attempt:now})}
 finally{clearTimeout(timer);if(version===nhRequestVersion){nhPlaceRequest=null;if(location.hash===requestedHash)render()}}
}
function nhOpenPlace(key){const item=nhPlaceEntry()?.items?.find(p=>p.key===key);if(!item)return;modal(`<h2>${esc(item.name)}</h2><p>${Math.round(item.distance)} м · Сонгосон төвөөс шулуун зай</p><p class="notice">OpenStreetMap мэдээлэл · Хаяг, ажиллах цагийг байгууллагаас нягтална уу.</p><a class="nh-text-link" href="https://www.openstreetmap.org/${item.key}" target="_blank" rel="noopener noreferrer">OpenStreetMap дээр харах ${icon('external-link')}</a>`)}
function destroyNeighborhoodMap(){nhMapObserver?.disconnect();nhMapObserver=null;nhMap?.remove();nhMap=null}
function mountNeighborhoodMap(){
 const host=document.getElementById('nh-map');if(!host)return;const status=document.querySelector('.nh-map-status'),fail=()=>{if(status){status.hidden=false;status.textContent='Газрын зураг ачаалсангүй. Зарууд хэсгийн жагсаалтыг ашиглана уу.'}};
 if(typeof maplibregl==='undefined')return fail();const center=nhMapCenter();
 try{nhMap=new maplibregl.Map({container:host,style:'https://tiles.openfreemap.org/styles/liberty',center:center?[center.lng,center.lat]:[103.8,46.9],zoom:center?(nhTab==='map'&&nhPlaceEntry()?.status==='success'?14:nhScope.area?11:10):4,minZoom:3,maxZoom:18,attributionControl:true});const map=nhMap;
  const groups=new Map();for(const h of nhHomes()){const p=listingLocationPoint(h);if(!p)continue;const exact=Number.isFinite(h.latitude)&&Number.isFinite(h.longitude),key=exact?'listing-'+h.id:h.area;const group=groups.get(key)||{lat:p[0],lng:p[1],homes:[],exact};group.homes.push(h);groups.set(key,group)}
  for(const group of groups.values()){const b=document.createElement('button');b.type='button';b.className='nh-map-marker';b.textContent=group.exact?'1':String(group.homes.length);b.setAttribute('aria-label',(group.exact?group.homes[0].name:group.homes[0].area+' · Ерөнхий төв')+' · '+group.homes.length+' зар');b.addEventListener('click',()=>{if(group.exact)detail(group.homes[0].id);else nhNavigate({...nhScope,area:group.homes[0].area,khoroo:''},'listings')});new maplibregl.Marker({element:b}).setLngLat([group.lng,group.lat]).addTo(map)}
  if(nhTab==='map')for(const item of nhPlaceEntry()?.items||[]){const b=document.createElement('button');b.type='button';b.className='nh-place-marker';b.innerHTML=icon(NH_PLACES[nhPlaceCategory].icon);b.setAttribute('aria-label',item.name);b.addEventListener('click',()=>nhOpenPlace(item.key));new maplibregl.Marker({element:b}).setLngLat([item.lng,item.lat]).addTo(map)}
  map.on('load',()=>{if(status)status.hidden=true});map.on('error',fail);if(typeof ResizeObserver!=='undefined'){nhMapObserver=new ResizeObserver(()=>nhMap?.resize());nhMapObserver.observe(host)}
 }catch{fail()}
}
function nhNoticeCards(limit=99){const all=nhNotices().slice(0,limit);return all.length?'<div class="nh-news-list">'+all.map(n=>`<a href="#/notice/${encodeURIComponent(n.id)}"><span>${icon('bell')}</span><div><small>${n.province?esc(nhScopeLabel(n)):'ӨРӨӨ · Платформын мэдээ'}</small><h3>${esc(n.title)}</h3><p>${esc(String(n.body).slice(0,120))}</p><time>${esc(n.date||'')}</time></div>${icon('chevron-right')}</a>`).join('')+'</div>':nhEmpty('Нийтэлсэн мэдээ одоогоор алга','Энэ бүсийн нийтэлсэн зарлал энд харагдана.')}
function nhNewsSection(){return `<section class="nh-panel">${nhHeading('МЭДЭЭ БА ЗАРЛАЛ','Хорооллын мэдээлэл',`<a href="#/notice">Бүх мэдээ ${icon('arrow-right')}</a>`)}<p class="nh-muted">Сонгосон бүсийн зарлал болон платформын нийтлэг мэдээ. Байгууллагын албан эх сурвалжийг тусад нь нягтална уу.</p>${nhNoticeCards()}</section><section class="nh-panel">${nhHeading('АЛБАН ЭХ СУРВАЛЖУУД','Мэдээллээ эх сурвалжаас нь')}<div class="nh-official-sources">${NH_SOURCES.filter(s=>!s.ub||nhScope.province==='Улаанбаатар').map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer"><i>${icon(s.icon)}</i><div><span>Гадаад эх сурвалж</span><h3>${s.title}</h3><p>${s.body}</p><small>${s.source}</small></div>${icon('external-link')}</a>`).join('')}</div><p class="nh-source-note">Эдгээр нь эх сурвалжийн холбоосууд. Шууд API холболт, одоогийн агаарын чанар, автобус ирэх хугацаа энэ хуудсанд холбогдоогүй.</p></section>`}
function nhPostCards(list){return list.length?`<div class="nh-post-list">${list.map(p=>{const liked=nhState().likes.includes(String(p.id)),kind=NH_CATEGORIES.find(c=>c[0]===p.category)?.[1]||'Нийтлэл';return `<article><div class="nh-post-meta"><span>${kind}</span><small>${esc(nhScopeLabel(p))}</small></div><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p><footer><span>${esc(p.author||'Локал демо нийтлэл')} · ${esc(p.date||'')}</span><button data-post="${esc(p.id)}" aria-label="Нийтлэлд таалагдах" aria-pressed="${liked}" onclick="nhLikePost(this.dataset.post)">${heartIcon(liked)}${liked?1:0}</button></footer></article>`}).join('')}</div>`:nhEmpty('Энэ бүсийн яриаг эхлүүлээрэй','Асуулт, амьдрах туршлага, хэрэгтэй зөвлөгөөгөө хуваалцаарай.','<button class="nh-small-button" onclick="communityPost()">'+icon('plus')+'Нийтлэл бичих</button>')}
function nhStoriesSection(){const legacy=nhLegacyPosts();return `<section class="nh-panel">${nhHeading('ХӨРШҮҮДИЙН ЯРИА','Өөрийн хорооллыг хамтдаа',`<button class="nh-small-button" onclick="communityPost()">${icon('plus')}Нийтлэл бичих</button>`)}<p class="nh-muted">Зөвхөн энэ браузерт хадгалсан демо нийтлэл. Бодит оршин суугчийн болон DAN баталгаажуулалтгүй.</p><div class="nh-story-categories">${[['all','Бүгд'],...NH_CATEGORIES].map(([key,label])=>`<button aria-pressed="${key===nhStoryCategory}" onclick="nhStoryCategory='${key}';render()">${label}</button>`).join('')}</div>${nhPostCards(nhPosts())}${legacy.length?`<button class="nh-legacy-link" onclick="nhShowLegacyPosts()">Байршилгүй өмнөх ${legacy.length} нийтлэл ${icon('arrow-right')}</button>`:''}</section>`}
function nhCommunityPost(){nhReadRoute();modal(`<div class="nh-compose"><span class="nh-eyebrow">ХӨРШҮҮДДЭЭ ХУВААЛЦАХ</span><h2>Нийтлэл бичих</h2><p class="nh-compose-region">${icon('pin')}${esc(nhScopeLabel())}</p><form onsubmit="nhSubmitPost(event)"><input type="hidden" name="scope" value="${esc(nhScopeKey())}"><label class="field">Төрөл<select name="category">${NH_CATEGORIES.map(([k,t])=>`<option value="${k}">${t}</option>`).join('')}</select></label><label class="field">Гарчиг<input name="title" required maxlength="100"></label><label class="field">Агуулга<textarea name="body" required maxlength="1500" rows="5"></textarea></label><p class="nh-source-note">Локал демо. Энэ браузерт хадгална. Хувийн регистр, үнэмлэх, нууц мэдээлэл бүү бичээрэй.</p><p class="nh-form-error" role="alert"></p><div class="flow-actions"><button type="button" onclick="closeOverlay()">Буцах</button><button class="primary">Нийтлэл хадгалах</button></div></form></div>`);document.querySelector('.modal').classList.add('nh-compose-modal')}
function nhSubmitPost(event){event.preventDefault();const f=new FormData(event.target),title=String(f.get('title')||'').trim(),body=String(f.get('body')||'').trim(),key=String(f.get('scope')||''),scope=nhScopeFromKey(key),category=String(f.get('category')||'question');if(!title||title.length>100||!body||body.length>1500||nhScopeKey(scope)!==key||!NH_CATEGORIES.some(c=>c[0]===category)){const error=event.target.querySelector('.nh-form-error');if(error)error.textContent='Гарчиг, агуулга болон байршлаа шалгана уу.';return}const record={id:flowId(),title,body,date:flowDate(),...scope,category,author:flowState.profile.demo?flowState.profile.name:'Зочин · Демо'};flowState.posts.unshift(record);if(!persistFlows()){flowState.posts.shift();return}closeOverlay();render();toast('Нийтлэлийг сонгосон бүсэд хадгаллаа.')}
function nhLikePost(id){if(!nhPosts('all').some(p=>String(p.id)===String(id)))return;const s=nhState(),before=s.likes.slice();s.likes=s.likes.includes(id)?s.likes.filter(v=>v!==id):[...s.likes,id];if(!persistFlows()){s.likes=before;return}render()}
function nhShowLegacyPosts(){modal(`<h2>Байршилгүй өмнөх нийтлэлүүд</h2><p class="notice">Өмнө хадгалсан нийтлэлд байршил оруулаагүй тул аль нэг хорооллын мэдээлэлд тооцохгүй.</p>${nhLegacyPosts().map(p=>`<article class="nh-legacy-post"><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p></article>`).join('')}`)}
function nhNoticeFields(n={}){return `<fieldset class="nh-admin-region"><legend>Мэдээний байршил ба эх сурвалж</legend><label class="admin-field">Хот / Аймаг<select name="province" onchange="nhNoticeProvinceChanged(this)"><option value="">Бүх бүс · Платформын мэдээ</option>${MONGOLIA_PROVINCES.map(p=>`<option ${n.province===p?'selected':''}>${p}</option>`).join('')}</select></label><label class="admin-field">Дүүрэг<select name="area" onchange="nhNoticeAreaChanged(this)"><option value="">Бүх дүүрэг</option>${n.province==='Улаанбаатар'?Object.keys(UB_KHOROO_COUNTS).map(p=>`<option ${n.area===p?'selected':''}>${p}</option>`).join(''):''}</select></label><label class="admin-field">Хороо<select name="khoroo"><option value="">Бүх хороо</option>${n.province==='Улаанбаатар'&&n.area?Array.from({length:UB_KHOROO_COUNTS[n.area]||0},(_,i)=>(i+1)+'-р хороо').map(p=>`<option ${n.khoroo===p?'selected':''}>${p}</option>`).join(''):''}</select></label><label class="admin-field">Эх сурвалжийн нэр<input name="sourceLabel" maxlength="100" value="${esc(n.sourceLabel||'')}"></label><label class="admin-field">Эх сурвалжийн холбоос<input name="sourceUrl" type="url" value="${esc(n.sourceUrl||'')}" placeholder="https://"></label></fieldset>`}
function nhNoticeProvinceChanged(select){const area=select.form.querySelector('[name=area]');area.innerHTML='<option value="">Бүх дүүрэг</option>'+(select.value==='Улаанбаатар'?Object.keys(UB_KHOROO_COUNTS).map(p=>'<option>'+p+'</option>').join(''):'');select.form.querySelector('[name=khoroo]').innerHTML='<option value="">Бүх хороо</option>'}
function nhNoticeAreaChanged(select){select.form.querySelector('[name=khoroo]').innerHTML='<option value="">Бүх хороо</option>'+Array.from({length:UB_KHOROO_COUNTS[select.value]||0},(_,i)=>'<option>'+(i+1)+'-р хороо</option>').join('')}
function nhNoticeMeta(form,old={}){const province=form.has('province')?String(form.get('province')||''):old.province||'',scope=nhCleanScope({province,area:form.has('area')?String(form.get('area')||''):old.area||'',khoroo:form.has('khoroo')?String(form.get('khoroo')||''):old.khoroo||''}),sourceLabel=String(form.get('sourceLabel')??old.sourceLabel??'').trim(),sourceUrl=String(form.get('sourceUrl')??old.sourceUrl??'').trim();if(province&&!MONGOLIA_PROVINCES.includes(province)||sourceLabel.length>100||sourceUrl&&!validListingLink(sourceUrl))return null;return {province:province?scope.province:'',area:province?scope.area:'',khoroo:province?scope.khoroo:'',sourceLabel,sourceUrl}}
function nhNoticeSource(n){return `<div class="nh-notice-origin"><span>${n.province?esc(nhScopeLabel(n)):'ӨРӨӨ · Платформын мэдээ'}</span>${n.sourceLabel?'<b>'+esc(n.sourceLabel)+'</b>':''}${n.sourceUrl&&validListingLink(n.sourceUrl)?'<a href="'+esc(n.sourceUrl)+'" target="_blank" rel="noopener noreferrer">Эх сурвалж '+icon('external-link')+'</a>':''}</div>`}
